From 21ffc693907d2a415bc3d7d106627d745d06f07a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:55:29 +0100
Subject: [PATCH] containments/desktop: open the context menu with Shift+F10

Shift+F10, the usual Menu key replacement on keyboards without one, did
nothing in Folder View, so keyboard users couldn't open an item's menu.
Forward it to the Menu key handler, which opens it at the current item.

BUG: 519354
---
 containments/desktop/package/contents/ui/FolderView.qml | 2 ++
 1 file changed, 2 insertions(+)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..b8a6eb2e8e 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1046,6 +1046,8 @@ FocusScope {
                         dir.refresh();
                     } else if (event.matches(StandardKey.SelectAll)) {
                         positioner.setRangeSelected(0, count - 1);
+                    } else if (event.key === Qt.Key_F10 && event.modifiers === Qt.ShiftModifier) {
+                        Keys.menuPressed(event);
                     } else if ( (root.inPanel || !main.krunnerAvailable || Plasmoid.configuration.useTypeAhead) && event.text.length === 1 && (event.modifiers === Qt.NoModifier || event.modifiers === Qt.ShiftModifier || (event.modifiers & Qt.KeypadModifier)) ) {
                         typeAheadTimer.restart();
                         const charPressed = event.text.toLowerCase();
